  "app.makedc": "डिलिव्हरी चलन",
  "app.made": "जालें: {x}",
  "app.local": "डेटा होम उगडलें ना, देखून फकत ह्याच सायटीर ह्या ब्राउझरांत सेव आसा. फुडल्या फावटीं तें डेटा होमांत वतलें.",
  "app.vault": "ह्या ब्राउझराच्या डेटा होमांत सेव आसा, जें Nivesh Sahayak च्या दर टूलांत वांटून घेतलां. आमकां कांयच धाडनात.",
  "app.help": "हें कशें काम करता",
  "app.helpp": "billing., cash-memo. आनी credit-note. चेर केल्लीं बिलां हांगा आपसूक दिसतात. मेळिल्ले आनी दिल्ले पयशे हांगा बरयात; ॲप ते बिलांक जोडटा, ॲडव्हान्स दवरता आनी येणें आनी हातांतली कॅश काडटा.",
  "app.invfix": "हांगा चुकतीं जाल्लीं इनव्हॉयसां बिलिंग सायटीरूय पेड दिसतलीं.",
